function EventsScreen(){
 const [events,setEvents]=useDemoSession<DemoEvent[]>('events',initialEvents,validEvents);
 const [tasks,setTasks]=useDemoSession<DemoTask[]>('tasks',initialTasks,validTasks);
 const [costs,setCosts]=useDemoSession<DemoCost[]>('costs',initialCosts,validCosts);
 const [guests,setGuests]=useDemoSession<DemoGuest[]>('guests',initialGuests,validGuests);
 const [removing,setRemoving]=useState<string|null>(null);
 const [links]=useLinks();const [pending,setPending]=useState<{item:DemoEvent;from:string;impact:DateImpact}|null>(null);
 const [open,setOpen]=useState(false),[editing,setEditing]=useState<string|null>(null),[error,setError]=useState('');
 const [f,setF]=useState<Omit<DemoEvent,'id'>>({name:'',side:'Chung',date:'',time:'',venue:'',address:'',confirmed:false});
 const edit=(x?:DemoEvent)=>{setEditing(x?.id??null);setError('');setF(x?{name:x.name,side:x.side,date:x.date,time:x.time,venue:x.venue,address:x.address,confirmed:x.confirmed}:{name:'',side:'Chung',date:'',time:'',venue:'',address:'',confirmed:false});setOpen(true)};
 const deep=useDeepLink(events,edit,'buổi lễ');const removingEvent=events.find(x=>x.id===removing);
 const affectedTasks=tasks.filter(x=>removing&&eventId(x.event)===removing);
 const affectedCosts=costs.filter(x=>removing&&eventId(x.event)===removing);
 const affectedGuests=guests.filter(g=>g.events.some(ev=>removing&&eventId(ev)===removing));
 const removeEvent=()=>{if(!removingEvent)return;const id=removingEvent.id;setTasks(previous=>previous.map(x=>eventId(x.event)===id?{...x,event:'Mọi buổi'}:x));setCosts(previous=>previous.map(x=>eventId(x.event)===id?{...x,event:'Chung'}:x));setGuests(previous=>previous.map(g=>({...g,events:g.events.filter(ev=>eventId(ev)!==id)})));setEvents(previous=>previous.filter(x=>x.id!==id));setRemoving(null)};
 const submit=(e:React.FormEvent)=>{e.preventDefault();if(!f.name.trim()){setError('Hãy nhập tên buổi lễ.');return}if(f.confirmed&&(!f.date||!f.time||!f.venue.trim()||!f.address.trim())){setError('Để đánh dấu đã chốt, cần ngày, giờ, nơi và địa chỉ.');return}const item={...f,id:editing??`e${Date.now()}`,name:f.name.trim()};const old=editing?events.find(x=>x.id===editing):undefined;if(old&&old.date!==item.date&&(item.date||old.date)){setPending({item,from:old.date,impact:computeDateImpact(item.id,old.date,item.date,tasks.map(t=>({...t,event:eventId(t.event)})),costs.map(c=>({...c,event:eventId(c.event)})),links)});setOpen(false);return}setEvents(previous=>editing?previous.map(x=>x.id===editing?item:x):[...previous,item]);setOpen(false)};
  return <div className="max-w-3xl"><Header name={titles.events} subtitle="KẾ HOẠCH"/><PlannerTabs active="events"/><MissingNote text={deep.missing}/><p className="mb-5 text-muted-foreground">Mỗi buổi có giờ, nơi và lời mời khác nhau. Có thể để chưa chốt.</p><DemoAction onClick={()=>edit()}><Plus/> Thêm buổi lễ</DemoAction><div className="mt-4 space-y-3" aria-live="polite">{events.length===0&&<Note tone="warm">Chưa có buổi lễ nào. Hãy thêm buổi đầu tiên.</Note>}{events.map(x=><Panel key={x.id} item={x.id}><div className="flex flex-wrap items-start justify-between gap-2"><h2 className="text-xl">{x.name}</h2><Status tone={x.confirmed?'sage':'warm'}>{x.confirmed?'Đã chốt':'Chưa chốt'}</Status></div><p className="mt-2 text-xs leading-6">{x.side} · {x.date?fmtDate(x.date):'Chưa ghi ngày'} · {x.time||'Chưa chốt giờ'}<br/>{x.venue||'Chưa ghi nơi'}{x.address?` · ${x.address}`:''}</p><div className="mt-3 flex flex-wrap gap-2"><DemoAction variant="outline" onClick={()=>edit(x)}><Pencil className="size-4"/> Sửa</DemoAction><DemoAction variant="ghost" onClick={()=>setRemoving(x.id)}>Bỏ buổi</DemoAction></div></Panel>)}</div><Action to="/invitation/preview" variant="outline" className="mt-5">Xem thiệp <ArrowRight/></Action>
 <Dialog open={!!removingEvent} onOpenChange={value=>{if(!value)setRemoving(null)}}><DialogContent className="max-h-[92vh] w-[calc(100vw-24px)] max-w-lg overflow-y-auto rounded-lg bg-card p-5 text-foreground sm:p-6"><DialogHeader className="text-left"><DialogTitle className="font-display text-2xl">Bỏ {removingEvent?.name}?</DialogTitle><DialogDescription>Chỉ thay đổi dữ liệu trong phiên dùng thử; không xóa hồ sơ, việc hay khoản chi.</DialogDescription></DialogHeader><div className="space-y-2 text-sm"><p>{affectedTasks.length} việc sẽ chuyển sang Mọi buổi.</p><p>{affectedCosts.length} khoản chi sẽ chuyển sang Chung; số tiền và lịch trả giữ nguyên.</p><p>{affectedGuests.length} hồ sơ khách sẽ bỏ buổi này khỏi danh sách buổi mời; hồ sơ và số người vẫn giữ nguyên.</p><p>{links.filter(l=>l.eventIds.includes(removingEvent?.id??'')).length} link đang chọn buổi này sẽ báo “Buổi đã bị bỏ — cần chọn lại” và không được coi là sẵn sàng cho đến khi hai bạn chọn lại.</p></div><DialogFooter className="flex-col-reverse gap-2 sm:flex-row"><Button type="button" variant="outline" size="lg" className="min-h-11" onClick={()=>setRemoving(null)}>Giữ buổi</Button><Button type="button" size="lg" className="min-h-11" onClick={removeEvent}>Xác nhận bỏ buổi</Button></DialogFooter></DialogContent></Dialog>
 <DateImpactDialog open={!!pending} eventName={pending?.item.name??''} from={pending?.from??''} to={pending?.item.date??''} impact={pending?.impact??null} onCancel={()=>{setPending(null)}} onConfirm={shift=>{if(!pending)return;const p=pending;if(shift){const m=new Map(p.impact.tasks.map(t=>[t.id,t.to]));setTasks(prev=>prev.map(t=>{const due=m.get(t.id);return due?{...t,due}:t}))}setEvents(prev=>prev.map(x=>x.id===p.item.id?p.item:x));setPending(null)}}/>
 <DemoDialog open={open} onOpenChange={o=>{setOpen(o);if(!o)deep.onClosed()}} title={editing?'Sửa buổi lễ':'Thêm buổi lễ'} description="Thông tin chưa chốt vẫn có thể ghi lại." submitLabel={editing?'Lưu thay đổi (demo)':'Thêm buổi lễ'} onSubmit={submit}><FormField label="Tên buổi lễ *" id="event-name" error={error}><input id="event-name" autoFocus className={inputCls} value={f.name} onChange={e=>setF({...f,name:e.target.value})} aria-invalid={!!error}/></FormField><FormField label="Bên tổ chức" id="event-side"><select id="event-side" className={inputCls} value={f.side} onChange={e=>setF({...f,side:e.target.value})}>{['Chung','Nhà gái','Nhà trai'].map(x=><option key={x}>{x}</option>)}</select></FormField><div className="grid gap-3 sm:grid-cols-2"><FormField label="Ngày" id="event-date"><input id="event-date" type="date" className={inputCls} value={f.date} onChange={e=>setF({...f,date:e.target.value})}/></FormField><FormField label="Giờ" id="event-time"><input id="event-time" type="time" className={inputCls} value={f.time} onChange={e=>setF({...f,time:e.target.value})}/></FormField></div><FormField label="Địa điểm" id="event-venue"><input id="event-venue" className={inputCls} value={f.venue} onChange={e=>setF({...f,venue:e.target.value})}/></FormField><FormField label="Địa chỉ" id="event-address"><input id="event-address" className={inputCls} value={f.address} onChange={e=>setF({...f,address:e.target.value})}/></FormField><label className="flex min-h-11 items-center gap-2"><input type="checkbox" checked={f.confirmed} onChange={e=>setF({...f,confirmed:e.target.checked})}/> Đã chốt đầy đủ thông tin</label></DemoDialog></div>
}

type DemoEvent={id:string;name:string;side:string;date:string;time:string;venue:string;address:string;confirmed:boolean};
function HomeScreen(){
 const [events]=useDemoSession<DemoEvent[]>('events',initialEvents,validEvents);const [costs]=useDemoSession<DemoCost[]>('costs',initialCosts,validCosts);const [guests]=useDemoSession<DemoGuest[]>('guests',initialGuests,validGuests);const [stored]=useDemoSession<DemoTask[]>('tasks',initialTasks,validTasks);
 const [today,setToday]=useState('');useEffect(()=>setToday(vietnamToday()),[]);
 const candidates=stored.map(normalizeTask).filter(t=>t.status!=='Xong'&&t.due).sort((a,b)=>a.due.localeCompare(b.due));const priority=candidates[0];const next=candidates[1];
 const dueItems=costs.flatMap(cost=>cost.installments.filter(i=>i.amount>0&&i.due).map(due=>({cost,due}))).sort((a,b)=>a.due.due.localeCompare(b.due.due));const nextScheduled=dueItems[0];const nextCost=nextScheduled?.cost??costs.find(x=>unpaidCost(x)>0);const nextDue=nextScheduled?.due;const waiting=guests.filter(g=>g.state==='Chưa trả lời'||g.state==='Chưa gửi');
 const taskSummary=(task:DemoTask)=><><div className="flex flex-wrap items-start justify-between gap-2"><div className="min-w-0 flex-1"><h2 className="break-words font-display text-xl font-semibold">{task.title}</h2><p className="mt-1 text-xs text-muted-foreground">{eventName(task.event,events,'Mọi buổi')} · {task.owner} phụ trách</p></div><Status tone={task.status==='Chờ chốt'?'warm':'copper'}>{task.status}</Status></div><p className={`mt-2 text-sm ${taskDue(task,today).group==='overdue'?'font-semibold text-destructive':'text-muted-foreground'}`}>{taskDue(task,today).label}</p></>;
 return <div><Header name={titles.home} subtitle={today?new Intl.DateTimeFormat('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',weekday:'long',day:'numeric',month:'long'}).format(new Date()):'TỔNG QUAN'}/><p className="-mt-3 mb-7 text-muted-foreground">Những điều hai bạn đang chuẩn bị cho ngày cưới.</p><div className="grid gap-6 lg:grid-cols-[1.25fr_.75fr]"><div><SmallLabel>VIỆC CÓ HẠN GẦN NHẤT</SmallLabel><Panel className="border-l-[3px] border-l-primary">{priority?taskSummary(priority):<p className="text-sm text-muted-foreground">Chưa có việc chưa xong nào được đặt hạn.</p>}<Action to="/plan/tasks" variant="ghost" className="mt-3 px-0 text-primary">{priority?'Mở danh sách việc':'Đặt hạn cho việc'} <ArrowRight/></Action></Panel><div className="mt-7"><SmallLabel>TIẾP THEO</SmallLabel><div className="grid gap-3 sm:grid-cols-2"><Panel>{next?taskSummary(next):<p className="text-sm text-muted-foreground">Chưa có việc có hạn tiếp theo.</p>}<Action to="/plan/tasks" variant="ghost" className="mt-2 px-0 text-primary">Xem việc <ArrowRight/></Action></Panel><Panel><div className="mb-3 flex items-center justify-between"><Status>{nextDue?'KHOẢN SẮP PHẢI TRẢ':'CHƯA GHI HẠN TRẢ'}</Status><Wallet className="size-4"/></div><h2 className="text-xl">{nextCost?fmtMoney(nextDue?.amount??unpaidCost(nextCost)):'Chưa có khoản đã chốt'}</h2><p className="mt-1 text-xs text-muted-foreground">{nextCost?`${nextCost.title} · ${nextDue?.due?fmtDate(nextDue.due):'còn chưa ghi hạn'}`:'Xem sổ chi tiêu'}</p><Action to={nextCost?`/plan/budget#cost-${nextCost.id}`:'/plan/budget'} variant="ghost" className="mt-2 px-0 text-primary">Xem khoản <ArrowRight/></Action></Panel></div></div></div><div><SmallLabel>KHÁCH MỜI</SmallLabel><Panel className="bg-sage"><div className="font-display text-3xl font-semibold">{waiting.length} hồ sơ</div><p className="mt-2 text-xs">chưa có phản hồi trong sổ khách demo · {waiting.reduce((n,g)=>n+g.party,0)} người dự kiến</p><Action to="/guests" variant="ghost" className="mt-3 px-0 text-primary">Xem sổ khách <ArrowRight/></Action></Panel><div className="mt-7"><SmallLabel>HÀNH TRÌNH CỦA MÌNH</SmallLabel><Panel><Row title="Các buổi lễ" detail={`${events.length} buổi lễ trong phiên dùng thử`} to="/wedding/events"/><Row title="Lời mời Đường Hẹn" detail="Một mẫu cố định cho hai bạn" to="/invitation/content"/></Panel></div></div></div></div>
}

const initialEvents: DemoEvent[] = [{id:'e1',name:'Lễ gia tiên nhà gái',side:'Nhà gái',date:'2027-10-18',time:'07:00',venue:'Tư gia nhà gái',address:'24 Nguyễn Văn Cừ, Hà Nội',confirmed:true},{id:'e2',name:'Tiệc tối',side:'Chung',date:'2027-10-18',time:'',venue:'',address:'',confirmed:false}];
const validEvents=(v:unknown):v is DemoEvent[]=>Array.isArray(v)&&v.every(x=>x&&typeof x.id==='string'&&typeof x.name==='string'&&typeof x.side==='string'&&typeof x.date==='string'&&typeof x.time==='string'&&typeof x.venue==='string'&&typeof x.address==='string'&&typeof x.confirmed==='boolean');
export function useEventNames(){const [events]=useDemoSession<DemoEvent[]>('events',initialEvents,validEvents);return events}
export const eventId=(idOrName:string)=>initialEvents.find(e=>e.name===idOrName)?.id??idOrName;
export const eventName=(idOrName:string,events:DemoEvent[],fallback='Chung')=>events.find(e=>e.id===eventId(idOrName))?.name??(['Mọi buổi','Chung','Tất cả','Nhà trai','Nhà gái'].includes(idOrName)?idOrName:fallback);
const isDinner=(idOrName:string)=>eventId(idOrName)==='e2';
export function PlannerTabs({active}:{active:'tasks'|'events'|'budget'}){return <nav aria-label="Kế hoạch" className="mb-5 grid grid-cols-3 gap-1.5 sm:gap-2"><Action to="/plan/tasks" variant={active==='tasks'?'default':'outline'} className="px-1 text-xs sm:px-4 sm:text-sm">Việc cần làm</Action><Action to="/wedding/events" variant={active==='events'?'default':'outline'} className="px-1 text-xs sm:px-4 sm:text-sm">Các buổi lễ</Action><Action to="/plan/budget" variant={active==='budget'?'default':'outline'} className="px-1 text-xs sm:px-4 sm:text-sm">Ngân sách</Action></nav>}

export const inputCls = 'mt-2 h-11 w-full rounded-md border border-border bg-background px-3 text-sm font-normal focus:outline-none focus:ring-2 focus:ring-ring';
export function FormField({label,id,error,children}:{label:string;id:string;error?:string|undefined;children:React.ReactNode}){return <div><label htmlFor={id} className="block text-xs font-semibold text-foreground">{label}</label>{children}{error&&<p id={`${id}-err`} role="alert" className="mt-1 text-xs font-semibold text-destructive">{error}</p>}</div>}
export function DemoDialog({open,onOpenChange,title,description,children,onSubmit,submitLabel}:{open:boolean;onOpenChange:(o:boolean)=>void;title:string;description:string;children:React.ReactNode;onSubmit:(e:React.FormEvent)=>void;submitLabel:string}){const returnTo=useRef<HTMLElement|null>(null);if(open&&!returnTo.current&&typeof document!=='undefined')returnTo.current=document.activeElement as HTMLElement|null;return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent onCloseAutoFocus={e=>{const el=returnTo.current;returnTo.current=null;if(el){e.preventDefault();el.focus()}}} className="max-h-[92vh] w-[calc(100vw-24px)] max-w-lg overflow-y-auto rounded-lg p-5 sm:p-6"><DialogHeader className="text-left"><DialogTitle className="font-display text-2xl">{title}</DialogTitle><DialogDescription>{description}</DialogDescription></DialogHeader><form noValidate onSubmit={onSubmit} className="space-y-4"><div className="rounded-md bg-warm px-3 py-2 text-[11px] font-semibold text-foreground">Bản dùng thử: dữ liệu chỉ nằm trong phiên xem này, chưa được lưu vào tài khoản.</div>{children}<DialogFooter className="flex-col-reverse gap-2 sm:flex-row"><Button type="button" variant="outline" size="lg" className="min-h-11" onClick={()=>onOpenChange(false)}>Hủy</Button><Button type="submit" size="lg" className="min-h-11">{submitLabel}</Button></DialogFooter></form></DialogContent></Dialog>}
function parseMoney(v:string){return v.trim()===''?0:Number(v.replace(/[^\d]/g,''))}
const fmtMoney=(n:number)=>n.toLocaleString('vi-VN')+' đ';
export const fmtDate=(d:string)=>d?d.split('-').reverse().slice(0,2).join('/'):'';

export type { DemoTask } from '@/lib/task-demo';
export const initialTasks:DemoTask[]=[
 {id:'t1',kind:'table-count',title:'Dự tính số bàn tiệc nhà trai',event:'e2',due:'',owner:'Minh',status:'Cần làm'},
 {id:'t2',title:'Xác nhận danh sách khách',event:'Mọi buổi',due:'',owner:'Cả hai',status:'Cần làm'},
 {id:'t3',title:'Duyệt giờ đón dâu',event:'Mọi buổi',due:'',owner:'Lan',status:'Chờ chốt'},
];
export const validTasks=(v:unknown):v is DemoTask[]=>Array.isArray(v)&&v.every(x=>x&&typeof x.id==='string'&&typeof x.title==='string'&&typeof x.event==='string'&&typeof x.status==='string');
function TasksScreen(){
 const events=useEventNames();const [filter,setFilter]=useState('Tất cả');const [stored,setTasks]=useDemoSession<DemoTask[]>('tasks',initialTasks,validTasks);const tasks=stored.map(normalizeTask);
 const [today,setToday]=useState('');useEffect(()=>setToday(vietnamToday()),[]);
 const [open,setOpen]=useState(false);const emptyTask={title:'',event:'Mọi buổi',due:'',owner:'Cả hai',status:'Cần làm' as DemoTask['status'],outcome:'',note:'',plannedTables:'',reserveTables:'',kind:'standard' as NonNullable<DemoTask['kind']>};
 const [f,setF]=useState(emptyTask);const [err,setErr]=useState('');const [countErr,setCountErr]=useState('');const [editId,setEditId]=useState<string|null>(null);const [done,setDone]=useState('');
 const reset=()=>{setF(emptyTask);setErr('');setCountErr('');setEditId(null)};
 const submit=(e:React.FormEvent)=>{e.preventDefault();const title=f.title.trim();const countError=validateTableCount(f.kind,f.plannedTables,f.reserveTables,f.status);setErr(title?'':'Hãy nhập tên việc.');setCountErr(countError);if(!title||countError)return;
  const fields={title,event:eventId(f.event),due:f.due,owner:f.owner,status:f.status,outcome:f.outcome.trim(),note:f.note.trim(),kind:f.kind,...(f.kind==='table-count'?{plannedTables:f.plannedTables===''?undefined:Number(f.plannedTables),reserveTables:f.reserveTables===''?undefined:Number(f.reserveTables)}:{})};
  if(editId){setTasks(t=>t.map(x=>x.id===editId?{...normalizeTask(x),plannedTables:undefined,reserveTables:undefined,...fields}:x));setDone(`Đã lưu “${title}” trong phiên.`)}else{setTasks(t=>[...t,{id:`n${Date.now()}`,...fields,added:true}]);setDone(`Đã thêm “${title}” trong phiên.`);setFilter('Tất cả')}
  setOpen(false);reset();
 };
 const shown=tasks.filter(x=>inTaskFilter(x,filter,today));
 return <div className="max-w-4xl"><div className="flex flex-wrap items-end justify-between gap-x-3"><Header name={titles.tasks} subtitle="KẾ HOẠCH"/><DemoAction className="mb-6" onClick={()=>{reset();setOpen(true)}}><Plus/> Thêm việc</DemoAction></div><PlannerTabs active="tasks"/><p className="mb-6 text-muted-foreground">“Hôm nay” là việc đến hạn hôm nay; “Sắp hạn” gồm việc quá hạn và đến hạn trong 14 ngày tới, không gồm hôm nay hay việc đã xong. Việc xa hơn và chưa đặt hạn vẫn ở “Tất cả”.</p>
 <div className="mb-6 grid grid-cols-4 gap-1.5 sm:flex sm:gap-2" role="group" aria-label="Lọc việc">{['Hôm nay','Sắp hạn','Chờ chốt','Tất cả'].map(x=><DemoAction key={x} variant={filter===x?'default':'outline'} className="min-w-0 rounded-full px-1 text-[11px] sm:px-4 sm:text-sm" onClick={()=>setFilter(x)}>{x}</DemoAction>)}</div>
 <SmallLabel>{filter==='Tất cả'?`TẤT CẢ · ${tasks.length} VIỆC`:filter==='Hôm nay'?'ĐẾN HẠN HÔM NAY':filter==='Sắp hạn'?'QUÁ HẠN HOẶC TRONG 14 NGÀY TỚI':'ĐANG CHỜ CHỐT'}</SmallLabel><p role="status" className="mb-2 text-xs font-semibold text-sage-strong">{done}</p>
 <div className="space-y-3" aria-live="polite">{shown.length===0&&<Note tone="warm">{filter==='Tất cả'?'Chưa có việc nào. Hãy thêm việc đầu tiên.':filter==='Hôm nay'?'Không có việc chưa xong nào đến hạn hôm nay.':filter==='Sắp hạn'?'Không có việc quá hạn hay đến hạn trong 14 ngày tới. Việc có hạn xa hơn và chưa đặt hạn vẫn ở Tất cả.':'Chưa có việc nào đang chờ chốt.'}</Note>}{shown.map(x=>{const due=taskDue(x,today);return <Panel key={x.id} item={x.id}><div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0 flex-1"><h2 className="break-words text-xl">{x.title}</h2><p className="mt-1 text-xs text-muted-foreground">{eventName(x.event,events,'Mọi buổi')} · {x.owner} phụ trách{x.added?' · Mới thêm (demo)':''}</p></div><Status tone={x.status==='Xong'?'sage':x.status==='Chờ chốt'?'warm':'copper'}>{x.status==='Xong'?'Đã xong':x.status}</Status></div>
 <p className={`mt-2 text-sm ${due.group==='overdue'?'font-semibold text-destructive':'text-muted-foreground'}`}>{due.label}</p>
 {x.kind==='table-count'&&<><p className="mt-2 text-sm"><span className="font-semibold">Số bàn dự kiến:</span> {x.plannedTables===undefined?'Chưa nhập':`${x.plannedTables} bàn`} · <span className="font-semibold">Số bàn dự phòng:</span> {x.reserveTables===undefined?'Chưa nhập':`${x.reserveTables} bàn`}</p><p className="mt-1 text-xs text-muted-foreground">Hai bạn tự dự tính số bàn; không tự tính từ phản hồi tham dự, không thay đổi sổ khách hay ngân sách.</p></>}
 {x.outcome&&<p className="mt-2 break-words text-sm"><span className="font-semibold">Kết quả cần chốt:</span> {x.outcome}</p>}{x.note&&<p className="mt-1 break-words text-sm"><span className="font-semibold">Ghi chú:</span> {x.note}</p>}
 {x.id==='t2'&&<Action to="/guests" variant="ghost" className="mt-1 px-0 text-primary">Xem sổ khách <ArrowRight/></Action>}
 <DemoAction variant="ghost" className="mt-1 px-0 text-primary" onClick={()=>{setEditId(x.id);setErr('');setCountErr('');setF({title:x.title,event:x.event,due:x.due,owner:x.owner,status:x.status,outcome:x.outcome??'',note:x.note??'',kind:x.kind??'standard',plannedTables:x.plannedTables===undefined?'':String(x.plannedTables),reserveTables:x.reserveTables===undefined?'':String(x.reserveTables)});setOpen(true)}}><Pencil className="size-4"/> Sửa việc</DemoAction></Panel>})}</div>
 <SuggestionLibrary autoOpen={useFocusId()==='suggestions'}/><Action to="/plan/budget" variant="outline" className="mt-5">Xem ngân sách <ArrowRight/></Action>
 <DemoDialog open={open} onOpenChange={o=>{setOpen(o);if(!o)reset()}} title={editId?'Sửa việc':'Thêm việc'} description="Ghi việc cần làm và kết quả hai bạn muốn chốt." submitLabel={editId?'Lưu thay đổi':'Thêm việc'} onSubmit={submit}>
 <FormField label="Tên việc *" id="task-title" error={err}><input id="task-title" autoFocus value={f.title} maxLength={120} aria-invalid={!!err} aria-describedby={err?'task-title-err':undefined} onChange={e=>setF({...f,title:e.target.value})} className={inputCls} placeholder="Ví dụ: Đặt xe đón dâu"/></FormField>
 <FormField label="Loại việc" id="task-kind"><select id="task-kind" value={f.kind} onChange={e=>{setF({...f,kind:e.target.value as NonNullable<DemoTask['kind']>});setCountErr('')}} className={inputCls}><option value="standard">Việc thường</option><option value="table-count">Dự tính số bàn</option></select></FormField>
 <FormField label="Buổi lễ" id="task-event"><select id="task-event" value={f.event} onChange={e=>setF({...f,event:e.target.value})} className={inputCls}><option value="Mọi buổi">Mọi buổi</option>{events.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></FormField>
 <div className="grid gap-4 sm:grid-cols-2"><FormField label="Hạn" id="task-due"><input id="task-due" type="date" value={f.due} onChange={e=>setF({...f,due:e.target.value})} className={inputCls}/></FormField><FormField label="Người phụ trách" id="task-owner"><select id="task-owner" value={f.owner} onChange={e=>setF({...f,owner:e.target.value})} className={inputCls}>{['Cả hai','Lan','Minh'].map(x=><option key={x}>{x}</option>)}</select></FormField></div>
 <FormField label="Trạng thái" id="task-status"><select id="task-status" value={f.status} onChange={e=>setF({...f,status:e.target.value as DemoTask['status']})} className={inputCls}>{['Cần làm','Đang làm','Chờ chốt','Xong'].map(x=><option key={x} value={x}>{x==='Xong'?'Đã xong':x}</option>)}</select></FormField>
 {f.kind==='table-count'&&<><div className="grid gap-4 sm:grid-cols-2"><FormField label="Số bàn dự kiến" id="task-tables" error={countErr}><input id="task-tables" type="number" min="0" step="1" inputMode="numeric" value={f.plannedTables} aria-invalid={!!countErr} aria-describedby={countErr?'task-tables-err':undefined} onChange={e=>setF({...f,plannedTables:e.target.value})} className={inputCls}/></FormField><FormField label="Số bàn dự phòng" id="task-reserve"><input id="task-reserve" type="number" min="0" step="1" inputMode="numeric" value={f.reserveTables} aria-invalid={!!countErr} onChange={e=>setF({...f,reserveTables:e.target.value})} className={inputCls}/></FormField></div><p className="text-xs text-muted-foreground">Đây là số bàn hai bạn tự dự tính, không tự tính từ phản hồi tham dự; sửa ở đây không đổi sổ khách hay ngân sách.</p></>}
 <FormField label="Kết quả cần chốt" id="task-outcome"><input id="task-outcome" value={f.outcome} maxLength={200} onChange={e=>setF({...f,outcome:e.target.value})} className={inputCls} placeholder={editId==='t2'?'Đã cùng nhau xem lại sổ khách':editId==='t3'?'Giờ đón dâu đã thống nhất, ví dụ 07:00':'Hai bạn muốn chốt điều gì?'}/></FormField>
 {editId==='t2'&&<p className="text-xs text-muted-foreground">Đánh dấu đã xong khi hai bạn đã xem lại danh sách khách; việc này không tự xác nhận khách tham dự.</p>}
 <FormField label="Ghi chú" id="task-note"><textarea id="task-note" value={f.note} maxLength={500} rows={3} onChange={e=>setF({...f,note:e.target.value})} className={inputCls} placeholder="Thông tin cần nhớ"/></FormField>
 </DemoDialog></div>}

type Installment = {id:string; label:string; amount:number; due:string};
type DemoCost = {id:string;title:string;group:string;groupDetail?:string;event:string;payer:string;estimated:number|null;committed:number|null;paid:number;deposit:number;vendor:string;extra:number;installments:Installment[]};
const GROUPS=['Tiệc & địa điểm','Lễ gia tiên/ăn hỏi','Ảnh & trang phục','Di chuyển/hoa/trang trí','Khác'];
const sharedCostLabel='Dùng chung, không thuộc riêng buổi nào';
const costEventName=(event:string,events:DemoEvent[])=>event==='Chung'?sharedCostLabel:eventName(event,events,sharedCostLabel);
const initialCosts:DemoCost[]=[
  {id:'b1',title:'Tiệc cưới',group:'Tiệc & địa điểm',event:'Tiệc tối',payer:'Chung',estimated:null,committed:50000000,paid:10000000,deposit:10000000,vendor:'',extra:0,installments:[]},
  {id:'b2',title:'Ảnh cưới',group:'Ảnh & trang phục',event:'Chung',payer:'Cặp đôi',estimated:8000000,committed:null,paid:0,deposit:0,vendor:'',extra:0,installments:[]},
  {id:'b3',title:'Trang phục',group:'Ảnh & trang phục',event:'Chung',payer:'Cặp đôi',estimated:5000000,committed:null,paid:0,deposit:0,vendor:'',extra:0,installments:[]},
];
const validCosts=(v:unknown):v is DemoCost[]=>Array.isArray(v)&&v.every(x=>x&&typeof x.id==='string'&&typeof x.title==='string'&&typeof x.group==='string'&&(x.groupDetail===undefined||typeof x.groupDetail==='string')&&typeof x.event==='string'&&typeof x.payer==='string'&&(x.estimated===null||typeof x.estimated==='number')&&(x.committed===null||typeof x.committed==='number')&&typeof x.paid==='number'&&typeof x.deposit==='number'&&typeof x.extra==='number'&&Array.isArray(x.installments)&&x.installments.every((i:Installment)=>typeof i.id==='string'&&typeof i.label==='string'&&typeof i.amount==='number'&&typeof i.due==='string'));
// A confirmed extra increases the agreed supplier price, not a separate speculative expense.
const agreedCost=(x:DemoCost)=>x.committed===null?0:x.committed+x.extra;
const plannedCost=(x:DemoCost)=>x.committed===null?(x.estimated??0):agreedCost(x);
const unpaidCost=(x:DemoCost)=>Math.max(0,agreedCost(x)-x.paid);
const validMoney=(v:string)=>v.trim()===''||/^\d[\d.\s]*$/.test(v.trim());
type CostDraft={title:string;group:string;groupDetail:string;event:string;payer:string;estimated:string;committed:string;paid:string;deposit:string;vendor:string;extra:string;installments:{id:string;label:string;amount:string;due:string}[]};
const emptyCost=():CostDraft=>({title:'',group:'Tiệc & địa điểm',groupDetail:'',event:'Chung',payer:'Cặp đôi',estimated:'',committed:'',paid:'0',deposit:'0',vendor:'',extra:'0',installments:[]});
function BudgetScreen(){const events=useEventNames();
  const [cap,setCap]=useDemoSession<number>('cap',80000000,(v):v is number=>typeof v==='number'&&v>0&&v<=10_000_000_000);
  const [items,setItems]=useDemoSession<DemoCost[]>('costs',initialCosts,validCosts);
  const [filter,setFilter]=useState('Tất cả');const [payerFilter,setPayerFilter]=useState('Tất cả');
  const [open,setOpen]=useState(false);const [editing,setEditing]=useState<string|null>(null);
  const [capOpen,setCapOpen]=useState(false);const [capDraft,setCapDraft]=useState('');const [capErr,setCapErr]=useState('');
  const [f,setF]=useState<CostDraft>(emptyCost());const [errors,setErrors]=useState<Record<string,string>>({});
  const total=items.reduce((s,x)=>s+plannedCost(x),0),agreed=items.reduce((s,x)=>s+agreedCost(x),0),paid=items.reduce((s,x)=>s+x.paid,0),unpaid=items.reduce((s,x)=>s+unpaidCost(x),0);
  const installments=items.flatMap(x=>x.installments.map(i=>({...i,title:x.title,payer:x.payer,event:x.event}))).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));
   const visible=items.filter(x=>(filter==='Tất cả'||eventId(x.event)===filter||(filter!=='Chung'&&x.payer===filter))&&(payerFilter==='Tất cả'||x.payer===payerFilter));
   const edit=(item?:DemoCost)=>{setEditing(item?.id??null);setErrors({});setF(item?{title:item.title,group:item.group,groupDetail:item.groupDetail??'',event:eventId(item.event),payer:item.payer,estimated:item.estimated===null?'':String(item.estimated),committed:item.committed===null?'':String(item.committed),paid:String(item.paid),deposit:String(item.deposit),vendor:item.vendor,extra:String(item.extra),installments:item.installments.map(i=>({...i,amount:String(i.amount)}))}:emptyCost());setOpen(true)};const deep=useDeepLink(items,edit,'khoản chi');
  const submit=(e:React.FormEvent)=>{
    e.preventDefault();const n:Record<string,string>={};
    if(!f.title.trim())n['title']='Hãy nhập tên khoản chi.';
     if(f.group==='Khác'&&!f.groupDetail.trim())n['groupDetail']='Hãy ghi cụ thể khoản chi thuộc nhóm Khác.';
    for(const key of ['estimated','committed','paid','deposit','extra'] as const)if(!validMoney(f[key]))n[key]='Chỉ nhập số tiền không âm (đồng).';
    const estimated=f.estimated.trim()?parseMoney(f.estimated):null, committed=f.committed.trim()?parseMoney(f.committed):null, paid=parseMoney(f.paid),deposit=parseMoney(f.deposit),extra=parseMoney(f.extra);
    if(estimated===null&&committed===null)n['estimated']='Nhập tiền dự tính hoặc giá đã chốt.';
    if([estimated??0,committed??0,paid,deposit,extra].some(x=>x>10_000_000_000))n['estimated']='Số tiền quá lớn.';
    if(paid>0&&committed===null)n['paid']='Cần ghi giá đã chốt trước khi ghi tiền đã trả.';
    if(extra>0&&committed===null)n['extra']='Chỉ ghi phát sinh đã xác nhận sau khi có giá chốt.';
     if(committed!==null&&paid>committed+extra)n['paid']='Đã thanh toán không thể vượt giá đã chốt gồm phát sinh.';
    if(deposit>paid)n['deposit']='Tiền cọc không thể lớn hơn tiền đã thanh toán.';
    let scheduled=0;
    f.installments.forEach((i,index)=>{if(!validMoney(i.amount)||!i.amount.trim()||parseMoney(i.amount)<=0)n[`installment-${index}`]='Nhập số tiền đợt trả hợp lệ.';scheduled+=parseMoney(i.amount)});
    if(scheduled>Math.max(0,(committed??0)+extra-paid))n['schedule']='Tổng các đợt vượt phần còn phải trả.';
    if(f.installments.length&&committed===null)n['schedule']='Cần ghi giá đã chốt để lập lịch trả.';
    setErrors(n);if(Object.keys(n).length)return;
     const item:DemoCost={id:editing??`n${Date.now()}`,title:f.title.trim(),group:f.group,...(f.group==='Khác'?{groupDetail:f.groupDetail.trim()}:{}),event:eventId(f.event),payer:f.payer,estimated,committed,paid,deposit,vendor:f.vendor.trim(),extra,installments:f.installments.map(i=>({...i,amount:parseMoney(i.amount)}))};
    setItems(previous=>editing?previous.map(x=>x.id===editing?item:x):[...previous,item]);setOpen(false);
  };
  const saveCap=(e:React.FormEvent)=>{e.preventDefault();if(!capDraft.trim()||!validMoney(capDraft)||parseMoney(capDraft)<=0||parseMoney(capDraft)>10_000_000_000){setCapErr('Nhập mức dự định chi hợp lệ, lớn hơn 0.');return}setCap(parseMoney(capDraft));setCapOpen(false)};
  return <div className="max-w-4xl"><Header name={titles.budget} subtitle="KẾ HOẠCH"/><PlannerTabs active="budget"/><MissingNote text={deep.missing}/><h2 className="font-display text-2xl">Đám cưới của mình đang dự tính hết bao nhiêu?</h2><p className="mb-5 mt-2 text-sm text-muted-foreground">Ghi từng khoản để hai bạn và hai gia đình dễ cùng theo dõi.</p>
    <div className="mb-5 flex flex-wrap gap-2"><DemoAction onClick={()=>edit()}><Plus/> Thêm khoản chi</DemoAction><DemoAction variant="outline" onClick={()=>{setCapDraft(String(cap));setCapErr('');setCapOpen(true)}}><Pencil/> Đổi mức dự định chi</DemoAction></div>
     <section aria-label="Tổng hợp ngân sách" className="rounded-lg bg-foreground p-4 text-primary-foreground sm:p-5"><div className="text-xs font-semibold">Mức hai bạn dự định chi</div><div className="mt-1 break-words font-display text-4xl font-semibold" data-testid="budget-cap">{fmtMoney(cap)}</div><p className="mt-2 text-xs opacity-85">Mức hai bạn tự đặt để theo dõi; có thể đổi bất cứ lúc nào.</p><dl className="mt-5 space-y-1.5 border-t border-primary-foreground/25 pt-4 text-xs sm:text-sm" aria-live="polite">{[
       {label:'Tổng chi đang dự tính',value:fmtMoney(total),tone:'bg-stat-blue-soft'},
       {label:'Đã chốt giá',value:fmtMoney(agreed),tone:'bg-sage'},
       {label:'Đã thanh toán (gồm tiền cọc)',value:fmtMoney(paid),tone:'bg-card'},
       {label:'Còn phải trả cho khoản đã chốt',value:fmtMoney(unpaid),tone:'bg-warm'},
       {label:total>cap?'Cảnh báo: vượt mức dự định':'Chênh lệch tạm tính so với mức dự định',value:fmtMoney(Math.abs(cap-total)),tone:`bg-copper-soft border-l-[3px] ${total>cap?'border-l-destructive':'border-l-transparent'}`},
     ].map(row=><div key={row.label} className={`flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1 rounded-md px-3 py-2.5 text-foreground ${row.tone}`}><dt className="min-w-0 flex-1 font-medium">{row.label}</dt><dd className="break-words text-right font-bold">{row.value}</dd></div>)}</dl></section>
    <p className="mt-3 text-xs leading-relaxed text-muted-foreground">Tổng chi đang dự tính lấy giá đã chốt nếu có, nếu chưa thì lấy tiền dự tính; phát sinh đã xác nhận cộng vào giá đã chốt và phần còn phải trả. Mỗi khoản chung chỉ tính một lần. Đây là tổng những khoản đã ghi, chưa chắc đủ mọi chi phí. {cap>=total?`${fmtMoney(cap-total)} là chênh lệch ước tính, chưa tính khoản chưa ghi; không phải tiền đang có.`:`Đã vượt dự định ${fmtMoney(total-cap)}; chưa tính khoản chưa ghi.`} Tiền mừng không được tự trừ; số khách phản hồi không tự đổi giá tiệc.</p>
    <section className="mt-8"><SmallLabel>SẮP PHẢI TRẢ</SmallLabel>{installments.length?<div className="space-y-2">{installments.map(i=><Panel key={`${i.title}-${i.id}`}><div className="flex flex-wrap items-start justify-between gap-2"><div><h3 className="font-semibold">{i.title} · {i.label}</h3><p className="mt-1 text-xs text-muted-foreground">{i.due?fmtDate(i.due):'Chưa ghi ngày trả'} · {i.payer} trả</p></div><strong>{fmtMoney(i.amount)}</strong></div></Panel>)}</div>:<Note tone="warm">Chưa ghi lịch trả cho khoản nào. {unpaid>0?`Các khoản đã chốt còn phải trả ${fmtMoney(unpaid)}, nhưng chưa gán số này vào một hạn nào.`:'Chưa có khoản đã chốt cần trả.'}</Note>}</section>
     <section className="mt-8"><SmallLabel>CÁC KHOẢN ĐÃ GHI · {visible.length}/{items.length}</SmallLabel><div className="flex flex-wrap gap-2" role="group" aria-label="Lọc khoản theo buổi hoặc nhà">{['Tất cả','Chung','Nhà trai','Nhà gái',...events.map(e=>e.id)].map(x=><DemoAction key={x} variant={filter===x?'default':'outline'} className="rounded-full px-3 text-xs" onClick={()=>setFilter(x)}>{costEventName(x,events)}</DemoAction>)}</div><label className="mt-3 block max-w-xs text-xs font-semibold">Bên trả<select className={inputCls} value={payerFilter} onChange={e=>setPayerFilter(e.target.value)}>{['Tất cả','Cặp đôi','Nhà trai','Nhà gái','Chung'].map(x=><option key={x}>{x}</option>)}</select></label>
     {visible.length===0&&<Note tone="warm">Chưa có khoản nào phù hợp bộ lọc.</Note>}{GROUPS.map(group=>{const list=visible.filter(x=>x.group===group);return list.length?<div key={group} className="mt-6"><h3 className="mb-2 font-display text-xl">{group}</h3><div className="space-y-2">{list.map(x=><div id={`cost-${x.id}`} key={x.id}><Panel item={x.id}><div className="flex flex-wrap items-start justify-between gap-2"><div className="min-w-0"><h4 className="font-semibold">{x.title}</h4>{x.group==='Khác'&&<p className="mt-1 text-xs font-medium text-primary">{x.groupDetail?`Khác: ${x.groupDetail}`:'Khác (chưa ghi chi tiết)'}</p>}<p className="mt-1 text-xs text-muted-foreground">{costEventName(x.event,events)} · {x.payer} trả</p></div><DemoAction variant="outline" className="px-3 text-xs" onClick={()=>edit(x)}><Pencil className="size-4"/> Sửa</DemoAction></div><div className="mt-3 grid grid-cols-2 gap-x-4 gap-y-2 text-xs sm:grid-cols-3"><div>Tiền dự tính<br/><strong>{x.estimated===null?'Chưa ghi':fmtMoney(x.estimated)}</strong></div><div>Giá đã chốt (gồm phát sinh)<br/><strong>{x.committed===null?'Chưa chốt':fmtMoney(agreedCost(x))}</strong></div><div>Đã cọc<br/><strong>{fmtMoney(x.deposit)}</strong></div><div>Đã thanh toán<br/><strong>{fmtMoney(x.paid)}</strong></div><div>Còn phải trả<br/><strong>{x.committed===null?'Chưa chốt':fmtMoney(unpaidCost(x))}</strong></div><div>Ngày trả tiếp<br/><strong>{x.installments.length?([...x.installments].filter(i=>i.due).sort((a,b)=>a.due.localeCompare(b.due))[0]?.due?fmtDate([...x.installments].filter(i=>i.due).sort((a,b)=>a.due.localeCompare(b.due))[0]?.due??''):'Chưa ghi ngày trả'):'Chưa ghi lịch'}</strong></div></div>{x.extra>0&&<p className="mt-2 text-xs">Trong giá đã chốt có phát sinh đã xác nhận: {fmtMoney(x.extra)}</p>}{x.vendor&&<p className="mt-2 text-xs text-muted-foreground">Đối tác: {x.vendor}</p>}</Panel></div>)}</div></div>:null})}</section>
    <p className="mt-5 text-xs text-muted-foreground">Tiền cọc và thanh toán nhà cung cấp không liên quan đến gói thiệp 149.000 đ.</p>
    <DemoDialog open={open} onOpenChange={o=>{setOpen(o);if(!o)deep.onClosed()}} title={editing?'Sửa khoản chi':'Thêm khoản chi'} description="Các khoản chỉ được giữ trong phiên dùng thử." submitLabel={editing?'Lưu thay đổi (demo)':'Thêm khoản chi'} onSubmit={submit}>
      <FormField label="Tên khoản chi *" id="cost-title" error={errors['title']}><input id="cost-title" autoFocus value={f.title} onChange={e=>setF({...f,title:e.target.value})} className={inputCls} aria-invalid={!!errors['title']}/></FormField>
       <FormField label="Nhóm chi" id="cost-group"><select id="cost-group" value={f.group} onChange={e=>{setF({...f,group:e.target.value,groupDetail:e.target.value==='Khác'?f.groupDetail:''});setErrors(previous=>({...previous,groupDetail:''}))}} className={inputCls}>{GROUPS.map(x=><option key={x}>{x}</option>)}</select></FormField>
       {f.group==='Khác'&&<FormField label="Cụ thể là khoản gì? *" id="cost-group-detail" error={errors['groupDetail']}><input id="cost-group-detail" value={f.groupDetail} onChange={e=>setF({...f,groupDetail:e.target.value})} className={inputCls} maxLength={120} placeholder="Ví dụ: Quà cảm ơn / Phí phục vụ" aria-invalid={!!errors['groupDetail']} aria-describedby={errors['groupDetail']?'cost-group-detail-err':undefined}/></FormField>}
       <div><FormField label="Khoản chi này dành cho buổi nào?" id="cost-event"><select id="cost-event" value={f.event} onChange={e=>setF({...f,event:e.target.value})} className={inputCls}><option value="Chung">{sharedCostLabel}</option>{events.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></FormField><p className="mt-2 text-xs leading-relaxed text-muted-foreground">Ảnh cưới có thể dùng chung; tiền tiệc chọn đúng buổi tiệc. Mỗi khoản chỉ tính một lần.</p></div>
      <FormField label="Ai sẽ trả" id="cost-payer"><select id="cost-payer" value={f.payer} onChange={e=>setF({...f,payer:e.target.value})} className={inputCls}>{['Cặp đôi','Nhà trai','Nhà gái','Chung'].map(x=><option key={x}>{x}</option>)}</select></FormField>
      <div className="grid gap-4 sm:grid-cols-2">{([['estimated','Tiền dự tính (đ)'],['committed','Giá đã chốt (đ)'],['paid','Đã thanh toán (đ)'],['deposit','Trong đó tiền cọc (đ)'],['extra','Phát sinh đã xác nhận (đ)']] as const).map(([key,label])=><FormField key={key} label={label} id={`cost-${key}`} error={errors[key]}><input id={`cost-${key}`} inputMode="numeric" value={f[key]} onChange={e=>setF({...f,[key]:e.target.value})} className={inputCls} aria-invalid={!!errors[key]}/></FormField>)}</div>
      <p className="text-xs text-muted-foreground">Phát sinh đã xác nhận được cộng vào giá đã chốt và phần còn phải trả. Chỉ ghi sau khi có giá chốt.</p><FormField label="Ghi chú đối tác" id="cost-vendor"><input id="cost-vendor" value={f.vendor} onChange={e=>setF({...f,vendor:e.target.value})} className={inputCls}/></FormField>
      <fieldset className="space-y-3 border-t border-border pt-4"><legend className="font-semibold">Lịch trả cho nhà cung cấp</legend>{f.installments.map((i,index)=><div key={i.id} className="space-y-2 rounded-md border border-border p-3"><FormField label="Đợt trả" id={`installment-label-${index}`}><select id={`installment-label-${index}`} className={inputCls} value={i.label} onChange={e=>setF({...f,installments:f.installments.map((x,j)=>j===index?{...x,label:e.target.value}:x)})}>{['Cọc','Đợt tiếp','Cuối'].map(x=><option key={x}>{x}</option>)}</select></FormField><FormField label="Số tiền (đ)" id={`installment-amount-${index}`} error={errors[`installment-${index}`]}><input id={`installment-amount-${index}`} className={inputCls} inputMode="numeric" value={i.amount} onChange={e=>setF({...f,installments:f.installments.map((x,j)=>j===index?{...x,amount:e.target.value}:x)})}/></FormField><FormField label="Hạn trả (để trống nếu chưa chốt)" id={`installment-due-${index}`}><input id={`installment-due-${index}`} type="date" className={inputCls} value={i.due} onChange={e=>setF({...f,installments:f.installments.map((x,j)=>j===index?{...x,due:e.target.value}:x)})}/></FormField><DemoAction variant="ghost" onClick={()=>setF({...f,installments:f.installments.filter((_,j)=>j!==index)})}>Bỏ đợt này</DemoAction></div>)}{errors['schedule']&&<p role="alert" className="text-xs text-destructive">{errors['schedule']}</p>}<DemoAction variant="outline" onClick={()=>setF({...f,installments:[...f.installments,{id:`i${Date.now()}-${f.installments.length}`,label:'Đợt tiếp',amount:'',due:''}]})}><Plus/> Thêm đợt trả</DemoAction></fieldset>
    </DemoDialog>
    <DemoDialog open={capOpen} onOpenChange={setCapOpen} title="Đổi mức dự định chi" description="Mức này do hai bạn tự đặt, không phải số tiền mặt." submitLabel="Lưu mức (demo)" onSubmit={saveCap}><FormField label="Mức hai bạn dự định chi (đ) *" id="cap-value" error={capErr}><input id="cap-value" autoFocus inputMode="numeric" value={capDraft} onChange={e=>setCapDraft(e.target.value)} className={inputCls}/></FormField></DemoDialog>
  </div>
}

export type DemoGuest={id:string;name:string;phone:string;side:string;events:string[];party:number;state:string;added?:boolean};
export const initialGuests:DemoGuest[]=[{id:'g1',name:'Hà My',phone:'',side:'Nhà gái',events:['Lễ gia tiên nhà gái','Tiệc tối'],party:1,state:'Có đến'},{id:'g2',name:'Quang Tùng',phone:'',side:'Nhà trai',events:['Tiệc tối'],party:1,state:'Chưa trả lời'},{id:'g3',name:'Chị Khánh',phone:'',side:'Nhà gái',events:['Lễ gia tiên nhà gái'],party:3,state:'Chưa gửi'}];
export const validGuests=(v:unknown):v is DemoGuest[]=>Array.isArray(v)&&v.every(x=>x&&typeof x.id==='string'&&typeof x.name==='string'&&Array.isArray(x.events)&&typeof x.party==='number');
function GuestsScreen(){const events=useEventNames();const [guests,setGuests]=useDemoSession<DemoGuest[]>('guests',initialGuests,validGuests);const [q,setQ]=useState('');const [guestFilter,setGuestFilter]=useState('Mọi buổi');const [guestSide,setGuestSide]=useState('Nhà gái');const [guestEvent,setGuestEvent]=useState('');const [open,setOpen]=useState(false);const empty={name:'',phone:'',side:'Nhà gái',events:[] as string[],party:'1'};const [f,setF]=useState(empty);const [errs,setErrs]=useState<Partial<Record<'name'|'phone'|'events'|'party',string>>>({});const [editId,setEditId]=useState<string|null>(null);const [done,setDone]=useState('');
const editGuest=(g:DemoGuest)=>{setEditId(g.id);setErrs({});setF({name:g.name,phone:g.phone,side:g.side,events:g.events.map(eventId),party:String(g.party)});setOpen(true)};const deep=useDeepLink(guests,editGuest,'khách');
const totalPeople=guests.reduce((n,g)=>n+g.party,0),dinnerPeople=guests.filter(g=>g.events.some(ev=>isDinner(ev)&&events.some(e=>e.id==='e2'))).reduce((n,g)=>n+g.party,0);
const norm=(s:string)=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/gi,'d').toLowerCase();const digits=q.replace(/\D/g,'');const shown=guests.filter(g=>(!q.trim()||norm(g.name).includes(norm(q.trim()))||(digits.length>2&&g.phone.replace(/\D/g,'').includes(digits)))&&(guestFilter==='Mọi buổi'||(guestFilter==='Theo nhà'&&g.side===guestSide)||(guestFilter==='Chưa phản hồi'&&g.state==='Chưa trả lời')||(guestFilter==='Theo buổi'&&g.events.some(ev=>eventId(ev)===(guestEvent||events[0]?.id)))));
const submit=(e:React.FormEvent)=>{e.preventDefault();const n:Partial<Record<'name'|'phone'|'events'|'party',string>>={};const name=f.name.trim();const phone=f.phone.trim();const party=Number(f.party);if(!name)n.name='Hãy nhập tên khách.';if(phone&&!/^\+?[\d\s.-]{8,15}$/.test(phone))n.phone='Số điện thoại chưa hợp lệ.';if(f.events.length===0)n.events='Chọn ít nhất một buổi lễ.';if(!Number.isInteger(party)||party<1||party>20)n.party='Từ 1 đến 20 người.';setErrs(n);if(Object.keys(n).length)return;if(editId){setGuests(g=>g.map(x=>x.id===editId?{...x,name,phone,side:f.side,events:f.events.map(eventId),party}:x));setOpen(false);setEditId(null);setDone(`Đã lưu ${name} trong phiên.`);return}setDone(`Đã thêm ${name} trong phiên.`);setGuests(g=>[{id:`n${Date.now()}`,name,phone,side:f.side,events:f.events.map(eventId),party,state:'Chưa gửi',added:true},...g]);setOpen(false);setF(empty);setQ('')};
return <div className="max-w-4xl"><Header name={titles.guests} subtitle="KHÁCH MỜI"/><MissingNote text={deep.missing}/><p className="-mt-3 mb-5 text-muted-foreground">Danh sách những người thân mến.</p><div className="grid grid-cols-2 gap-3" aria-live="polite"><Panel className="bg-foreground text-primary-foreground"><div className="text-xs">Tất cả</div><div className="font-display text-3xl font-bold">{totalPeople} người dự kiến</div></Panel><Panel><div className="text-xs">Tiệc tối</div><div className="font-display text-3xl font-bold">{dinnerPeople} người dự kiến</div></Panel></div><p className="mt-2 text-xs text-muted-foreground">{guests.length} hồ sơ khách · một hồ sơ có thể gồm nhiều người; khách dự nhiều buổi chỉ tính một lần ở tổng.</p><div className="mt-4 flex flex-wrap gap-2"><Action to="/guests/import" className="flex-1"><Upload/> Nhập CSV</Action><Action to="/guests/export" variant="outline" className="flex-1"><Download/> Xuất CSV</Action><DemoAction variant="outline" className="flex-1" onClick={()=>{setF(empty);setErrs({});setEditId(null);setOpen(true)}}><Plus/> Thêm khách</DemoAction></div><label htmlFor="guest-search" className="sr-only">Tìm khách</label><input id="guest-search" type="search" value={q} onChange={e=>setQ(e.target.value)} placeholder="Tìm tên hoặc số điện thoại" className="mt-5 h-11 w-full rounded-md border border-border bg-card px-4"/><div className="mt-4 flex flex-wrap gap-2" role="group" aria-label="Lọc khách">{['Mọi buổi','Theo buổi','Theo nhà','Chưa phản hồi'].map(x=><DemoAction key={x} variant={guestFilter===x?'default':'outline'} className="rounded-full px-3 text-xs" onClick={()=>setGuestFilter(x)}>{x}</DemoAction>)}</div>{guestFilter==='Theo nhà'&&<label className="mt-2 block text-xs">Chọn nhà<select className={inputCls} value={guestSide} onChange={e=>setGuestSide(e.target.value)}>{['Nhà gái','Nhà trai','Cả hai'].map(x=><option key={x}>{x}</option>)}</select></label>}{guestFilter==='Theo buổi'&&<label className="mt-2 block text-xs">Chọn buổi<select className={inputCls} value={events.some(ev=>ev.id===guestEvent)?guestEvent:events[0]?.id??''} onChange={e=>setGuestEvent(e.target.value)}>{events.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label>}<p className="mt-3 text-xs font-semibold text-sage-strong" role="status">{done}</p><p className="mt-1 text-xs">{shown.length} hồ sơ phù hợp · {shown.reduce((n,g)=>n+g.party,0)} người dự kiến</p><div className="mt-4 space-y-2">{shown.length===0&&<Note tone="warm">Không tìm thấy khách phù hợp.</Note>}{shown.map(g=><Panel key={g.id} item={g.id}><Row title={g.name} detail={`${g.side} · ${g.events.filter(ev=>events.some(e=>e.id===eventId(ev))).map(ev=>eventName(ev,events)).join(' + ')||'Chưa chọn buổi'}${g.party>1?` · ${g.party} người`:''}${g.phone?` · ${g.phone}`:''}${g.added?' · Mới thêm (demo)':''}`} right={<Status tone={g.state==='Có đến'?'sage':'warm'}>{g.state}</Status>}/><DemoAction variant="ghost" className="px-0 text-primary" onClick={()=>editGuest(g)}><Pencil className="size-4"/> Sửa khách</DemoAction></Panel>)}</div><p className="mt-4 text-xs text-muted-foreground">Một khách có thể được mời nhiều buổi lễ mà không nhân đôi hồ sơ. Số liệu là dữ liệu minh họa.</p><Action to="/rsvp" variant="outline" className="mt-4">Xem phản hồi <ArrowRight/></Action>
<DemoDialog open={open} onOpenChange={o=>{setOpen(o);if(!o)deep.onClosed()}} title={editId?"Sửa khách":"Thêm khách"} description="Thêm một người hoặc một nhóm đi cùng." submitLabel={editId?"Lưu thay đổi":"Thêm khách"} onSubmit={submit}><FormField label="Tên khách *" id="guest-name" error={errs.name}><input id="guest-name" autoFocus value={f.name} maxLength={100} aria-invalid={!!errs.name} onChange={e=>setF({...f,name:e.target.value})} className={inputCls} placeholder="Ví dụ: Cô Hạnh"/></FormField><FormField label="Số điện thoại (không bắt buộc)" id="guest-phone" error={errs.phone}><input id="guest-phone" type="tel" inputMode="tel" value={f.phone} aria-invalid={!!errs.phone} onChange={e=>setF({...f,phone:e.target.value})} className={inputCls} placeholder="09xx xxx xxx"/></FormField><FormField label="Bên nào mời" id="guest-side"><select id="guest-side" value={f.side} onChange={e=>setF({...f,side:e.target.value})} className={inputCls}>{['Nhà gái','Nhà trai','Cả hai'].map(x=><option key={x}>{x}</option>)}</select></FormField><fieldset><legend className="text-xs font-semibold">Mời dự buổi *</legend><div className="mt-2 space-y-1">{events.map(ev=><label key={ev.id} className="flex min-h-11 items-center gap-3 rounded-md border border-border px-3 text-sm"><input type="checkbox" className="size-4 accent-primary" checked={f.events.some(id=>eventId(id)===ev.id)} onChange={e=>setF({...f,events:e.target.checked?[...f.events,ev.id]:f.events.filter(x=>eventId(x)!==ev.id)})}/>{ev.name}</label>)}</div>{errs.events&&<p role="alert" className="mt-1 text-xs font-semibold text-destructive">{errs.events}</p>}</fieldset><FormField label="Số người dự kiến (kể cả khách)" id="guest-party" error={errs.party}><input id="guest-party" type="number" min={1} max={20} value={f.party} aria-invalid={!!errs.party} onChange={e=>setF({...f,party:e.target.value})} className={inputCls}/></FormField></DemoDialog></div>}
type InviteDraft={title:string;message:string};
const initialInvite:InviteDraft={title:'Lan & Minh',message:'Hai gia đình thân mời bạn đến chung vui trong ngày Lan và Minh về chung một nhà.'};
const validInvite=(v:unknown):v is InviteDraft=>!!v&&typeof v==='object'&&typeof (v as InviteDraft).title==='string'&&typeof (v as InviteDraft).message==='string';
function PhotoStrip(){const photos=usePhotos();if(!photos.length)return null;const top=photos.slice(0,6);return <div className="mt-6" data-testid="invite-photos"><div className="grid grid-cols-3 gap-1.5">{top.map(p=><img key={p.id} src={p.url} alt={p.name} className="aspect-square w-full rounded-md object-cover"/>)}</div><p className="mt-1 text-center text-[11px] text-muted-foreground">{photos.length} ảnh{photos.length>6?` (hiện 6)`:''} · ảnh chỉ trên máy này, chưa tải lên</p></div>}
/** Thiệp dùng CÙNG cấu hình link (side + eventIds) với trang khách; `shown` truyền vào từ linkView. */
function InviteCard({compact=false,side='nha-gai',draft,shown:shownIn}:{compact?:boolean;side?:EventSide;draft?:InviteDraft;shown?:DemoEvent[]}){
 const [invite]=useDemoSession<InviteDraft>('invite',initialInvite,validInvite);
 const [events]=useDemoSession<DemoEvent[]>('events',initialEvents,validEvents);
 const [links]=useLinks();
 const cfg=links.find(l=>l.side===side);
 const shown=shownIn??(cfg?events.filter(e=>cfg.eventIds.includes(e.id)):[]);
 return <div className={`relative overflow-hidden rounded-lg border border-border bg-background ${compact?'p-6':'p-7 sm:p-10'}`}><div className="border-b border-border pb-4 text-center text-[10px] font-bold uppercase text-primary">ĐƯỜNG HẸN · {SIDE_LABEL[side]}</div><div className="relative mt-7 h-8"><div className="absolute left-0 top-0 h-px w-1/2 origin-right rotate-[8deg] bg-primary"/><div className="absolute right-0 top-0 h-px w-1/2 origin-left -rotate-[8deg] bg-primary"/><div className="absolute left-1/2 top-4 size-1.5 -translate-x-1/2 rounded-full bg-foreground"/></div><h2 className="mt-3 break-words text-center text-[36px] font-semibold leading-none">{draft?.title??invite.title}</h2><p className="mt-4 whitespace-pre-wrap break-words text-center text-sm leading-relaxed">{draft?.message??invite.message}</p><PhotoStrip/><div className="mt-6"><SmallLabel>BUỔI LỄ CỦA CHÚNG MÌNH</SmallLabel>{shown.length===0&&<Note tone="warm">Chưa có buổi lễ cho link này.</Note>}{shown.map(e=><Panel key={e.id} className="mb-2"><h3 className="text-2xl">{e.name}</h3><div className="mt-3 flex flex-wrap gap-2 border-t border-border pt-4 text-xs font-semibold"><span>{e.time||'Chưa chốt giờ'}</span><span>·</span><span>{e.date?fmtDate(e.date):'Chưa chốt ngày'}</span></div><p className="mt-2 text-xs">{e.venue||'Chưa chốt nơi'}{e.address&&<><br/>{e.address}</>}</p>{e.address&&<a className="mt-4 inline-flex items-center gap-1 text-xs font-semibold text-primary underline-offset-2 hover:underline" href={mapUrl(e.address)} target="_blank" rel="noreferrer">Xem đường đi <ExternalLink className="size-3"/></a>}</Panel>)}</div><Note tone="copper">Có bạn, ngày vui thêm trọn vẹn.</Note></div>
}
function InvitationTabs({active}:{active:'content'|'preview'|'publish'}){return <nav aria-label="Thiệp" className="mb-5 grid grid-cols-3 gap-1.5 sm:gap-2"><Action to="/invitation/content" variant={active==='content'?'default':'outline'} className="px-1 text-xs sm:px-4 sm:text-sm">Nội dung</Action><Action to="/invitation/preview" variant={active==='preview'?'default':'outline'} className="px-1 text-xs sm:px-4 sm:text-sm">Xem trước</Action><Action to="/plans" variant={active==='publish'?'default':'outline'} className="px-1 text-xs sm:px-4 sm:text-sm">Công bố</Action></nav>}
function ContentScreen(){
 const [invite,setInvite]=useDemoSession<InviteDraft>('invite',initialInvite,validInvite);
 const [draft,setDraft]=useState(initialInvite);const [message,setMessage]=useState('');
 useEffect(()=>setDraft(invite),[invite.title,invite.message]);
 const update=()=>{if(!draft.title.trim()||!draft.message.trim()){setMessage('Hãy nhập tên hiển thị và lời mời.');return}if(draft.title.trim()===invite.title&&draft.message.trim()===invite.message){setMessage('Bản xem thử chưa có thay đổi.');return}setInvite({title:draft.title.trim(),message:draft.message.trim()});setMessage('Đã cập nhật bản xem thử trong phiên dùng thử.')};
  return <div><Header name={titles.content} subtitle="LỜI MỜI / ĐƯỜNG HẸN"/><InvitationTabs active="content"/><p className="mb-6 text-muted-foreground">Một mẫu Đường Hẹn cố định. Nội dung và ảnh của hai bạn tạo nên bản thiệp riêng.</p><div className="grid items-start gap-5 lg:grid-cols-[1fr_.85fr]"><Panel><h2 className="text-xl">Nội dung thiệp</h2><div className="mt-4 space-y-5"><FormField label="Tên hiển thị" id="invite-title"><input id="invite-title" value={draft.title} onChange={e=>{setDraft({...draft,title:e.target.value});setMessage('')}} className={inputCls}/></FormField><FormField label="Lời mời chung" id="invite-message"><textarea id="invite-message" value={draft.message} onChange={e=>{setDraft({...draft,message:e.target.value});setMessage('')}} rows={4} className="mt-2 w-full rounded-md border border-border bg-background p-3 text-sm"/></FormField><PhotoManager/></div><p role="status" className="mt-4 text-xs font-semibold text-primary">{message}</p><div className="mt-5 flex flex-wrap gap-2"><DemoAction onClick={update}>Cập nhật bản xem thử</DemoAction><Action to="/invitation/preview" variant="outline">Xem trên điện thoại <ArrowRight/></Action></div></Panel><div className="lg:sticky lg:top-24"><div className="mb-3 text-xs font-semibold">Bản xem trước · Link nhà gái (buổi theo cấu hình link)</div><InviteCard compact side="nha-gai" draft={draft}/><Note>Bản thử riêng, chỉ hai bạn nhìn thấy. Thông tin buổi lễ có thể sửa tại Thông tin ngày cưới.</Note></div></div><div className="mt-6"><Action to="/invitation/variants" variant="outline">Chọn link lời mời <ArrowRight/></Action></div></div>
}

function GuestClosed({kind}:{kind:'off'|'unknown'|'broken'}){if(kind==='broken')return <div className="mx-auto max-w-lg pt-16 text-center" data-testid="guest-closed"><h1 className="text-4xl">Thiệp chưa sẵn sàng</h1><p className="mt-4 text-muted-foreground">Hai bạn cần cập nhật buổi lễ trước khi lời mời này hiển thị. Xin quay lại sau hoặc liên hệ trực tiếp với gia đình.</p></div>;return <div className="mx-auto max-w-lg pt-16 text-center" data-testid="guest-closed"><h1 className="text-4xl">Thiệp chưa mở</h1><p className="mt-4 text-muted-foreground">{kind==='off'?'Lời mời này hiện không hiển thị.':'Không tìm thấy lời mời này.'} Nếu cần biết thêm thông tin, xin liên hệ trực tiếp với gia đình.</p></div>}
function PreviewScreen(){const [side,setSide]=useState<EventSide>('nha-gai');const [events]=useDemoSession<DemoEvent[]>('events',initialEvents,validEvents);const [links]=useLinks();const view=linkView(side,links,events);const cfg=links.find(l=>l.side===side);const r=cfg?linkReadiness(cfg.enabled,cfg.eventIds,events):null;
 return <div><Header name={titles.preview} subtitle="BẢN THỬ RIÊNG"/><InvitationTabs active="preview"/><p className="-mt-1 mb-5 text-muted-foreground">Đang xem {SIDE_LABEL[side].toLowerCase()} đúng như khách sẽ thấy · chỉ hai bạn nhìn thấy.</p><div className="mb-5 flex gap-2" role="group" aria-label="Chọn link">{(['nha-gai','chung','nha-trai'] as EventSide[]).map(x=><DemoAction key={x} aria-pressed={side===x} onClick={()=>setSide(x)} variant={side===x?'default':'outline'} className="flex-1 px-2 text-xs">{SIDE_LABEL[x]}</DemoAction>)}</div>
 <div className="grid gap-5 lg:grid-cols-[1fr_.9fr]"><div><Note tone={r?.readiness==='ready'?'sage':'warm'}>{!r?'Link này không tồn tại.':r.readiness==='off'?`${SIDE_LABEL[side]} đang tắt. Khách mở link sẽ thấy trang “Thiệp chưa mở”.`:r.readiness==='ready'?`${SIDE_LABEL[side]} · sẵn sàng. Có ${view.kind==='ok'?view.events.length:0} buổi trong link.`:`${SIDE_LABEL[side]} · cần sửa: ${r.missing.join(', ')}.${view.kind==='broken'?' Khách mở link sẽ thấy “Thiệp chưa sẵn sàng”, không trả lời được.':''}`}</Note>
 <Panel className="mt-4"><Row title="Cùng một cấu hình" detail="Bật/tắt và buổi đã chọn ở “Các phiên bản link” áp dụng cho bản xem trước, thiệp khách, phản hồi và biên nhận"/><Row title="Khách sẽ thấy" detail="Tên, giờ, nơi, bản đồ theo địa chỉ từng buổi và câu trả lời theo từng buổi"/></Panel>
 <div className="mt-5 grid gap-2"><Action to="/invitation/variants" variant="outline">Sửa bật/tắt và buổi của link <ArrowRight/></Action><Button asChild variant="ghost" size="lg" className="min-h-11"><Link to="/i/$token" params={{token:TOKEN_FOR_SIDE[side]}}>Mở như khách (minh họa)</Link></Button>{r?.readiness==='ready'?<Action to="/plans">Xem gói trước khi công bố <ArrowRight/></Action>:r?.readiness==='needs-fix'?<Action to="/invitation/check">Xem thông tin còn thiếu <ArrowRight/></Action>:null}</div></div>
 <div>{view.kind==='ok'?<InviteCard compact side={side} shown={view.events}/>:<Panel><GuestClosed kind={view.kind}/></Panel>}</div></div></div>}
function PlansScreen(){return <div className="max-w-3xl"><Header name={titles.plans} subtitle="CÔNG BỐ THIỆP"/><InvitationTabs active="publish"/><div className="mb-5 border-l-[3px] border-l-primary pl-4"><h2 className="font-display text-2xl">Hai bạn chuẩn bị miễn phí; chỉ trả khi muốn gửi thiệp cho khách và nhận phản hồi.</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Tên hai bạn và thông tin buổi lễ đã nhập được dùng lại trong thiệp Đường Hẹn; hai bạn xem trước riêng trước khi quyết định công bố.</p></div><Panel className="bg-sage"><SmallLabel>CHUẨN BỊ MIỄN PHÍ</SmallLabel><div className="mt-1 grid gap-3 sm:grid-cols-3"><div><strong>Kế hoạch cưới</strong><p className="mt-1 text-xs leading-5">Việc cần làm và ngân sách</p></div><div><strong>Khách mời</strong><p className="mt-1 text-xs leading-5">Danh sách khách và nhập CSV</p></div><div><strong>Thiệp Đường Hẹn</strong><p className="mt-1 text-xs leading-5">Nhập lời và xem trước riêng một mẫu cố định</p></div></div></Panel><Panel className="mt-4 border-l-[3px] border-l-primary"><div className="grid grid-cols-[minmax(0,1fr)_auto] items-start gap-3"><div className="min-w-0"><SmallLabel>GÓI THIỆP CƯỚI · MỘT ĐÁM CƯỚI</SmallLabel><h2 className="break-words text-3xl">149.000 đ <span className="block text-base font-sans font-semibold sm:inline">/ một đám cưới</span></h2><p className="mt-2 text-sm font-semibold">Thanh toán một lần</p></div><Status>24 tháng</Status></div><p className="mt-4 rounded-md bg-warm p-3 text-xs font-semibold leading-5">Link thiệp và phản hồi tham dự hoạt động 24 tháng kể từ khi thanh toán được xác minh. Không gia hạn, không thu phí định kỳ. Hết hạn, khách không thể mở thiệp hoặc gửi phản hồi.</p><div className="mt-4 border-t border-border"><Row title="Công bố & QR" detail="Tự duyệt rồi công bố tối đa 3 link: chung, nhà trai và nhà gái"/><Row title="Tối đa 50 ảnh" detail="Tối đa 50 ảnh cho một đám cưới. Bản dùng thử chưa lưu ảnh thật."/><Row title="Phản hồi tham dự công khai" detail="Khách trả lời theo từng buổi; hai bạn xem phản hồi trong ứng dụng"/></div></Panel><Panel className="mt-4"><h2 className="text-xl">Điều khoản quan trọng</h2><p className="mt-2 text-xs leading-6 text-muted-foreground">Thanh toán một lần cho một đám cưới. Hết 24 tháng, link thiệp và phản hồi dừng hoạt động. Chính sách hủy/hoàn tiền đầy đủ và ngày hết hạn cụ thể sẽ hiển thị trước khi thanh toán thật; bản dùng thử này chưa nhận tiền.</p></Panel><Note tone="warm"><strong>Bản dùng thử chưa nhận thanh toán.</strong><br/>Nút bên dưới chỉ mở đơn minh họa, không tạo giao dịch, không cấp quyền và không công bố thiệp.</Note><Action to="/checkout" className="mt-5 w-full">Xem đơn minh họa <ArrowRight/></Action></div>}
function CheckoutScreen({status=false}:{status?:boolean}){return <div className="max-w-3xl"><Header name={status?titles.status:titles.checkout} subtitle="ĐƠN MINH HỌA"/><p className="-mt-3 mb-5 text-muted-foreground">Đây là bước xem lại giá và thời hạn; chưa thu tiền hoặc mở quyền công bố.</p><Note tone="warm"><strong>Chưa ghi nhận giao dịch</strong><br/>Trạng thái minh họa này không xác nhận đã trả tiền. Quyền công bố chỉ mở sau khi giao dịch thật được xác minh.</Note><Panel className="mt-4"><SmallLabel>GÓI THIỆP CƯỚI · MỘT ĐÁM CƯỚI</SmallLabel><div className="grid grid-cols-[minmax(0,1fr)_auto] items-start gap-3"><div className="min-w-0"><span className="text-xs text-muted-foreground">Tổng đơn minh họa</span><strong className="mt-1 block break-words text-2xl">149.000 đ</strong></div><Status>Thanh toán một lần</Status></div><div className="mt-4 border-t border-border pt-4 text-xs leading-6"><p><strong>Thời hạn:</strong> 24 tháng kể từ khi thanh toán được xác minh.</p><p><strong>Bao gồm:</strong> công bố/QR tối đa 3 link, tối đa 50 ảnh và phản hồi tham dự công khai.</p><p><strong>Sau 24 tháng:</strong> link thiệp và phản hồi tham dự ngừng hoạt động.</p><p><strong>Gia hạn:</strong> không gia hạn, không thu phí định kỳ.</p></div></Panel><Panel className="mt-4"><div className="grid grid-cols-[88px_minmax(0,1fr)] items-center gap-4 sm:grid-cols-[100px_minmax(0,1fr)]"><div className="grid aspect-square place-items-center rounded-md border border-border bg-background text-center text-[10px] text-muted-foreground">QR MINH HỌA<br/>KHÔNG THANH TOÁN</div><div className="min-w-0"><strong className="text-xs">Thông tin chuyển khoản</strong><p className="mt-2 text-xs leading-5 text-muted-foreground">Chỉ hiển thị mã và tài khoản thật khi hệ thống thanh toán được kết nối.</p></div></div></Panel>{status&&<OrderStatusDemo/>}<Note>Vừa chuyển khoản? Đừng tạo đơn thứ hai. Trang này không thể tự xác minh hoặc cấp quyền.</Note>{status&&<Note tone="sage">Tình huống đã xác minh chỉ để kiểm tra giao diện tiếp theo. Đơn mẫu vẫn chưa ghi nhận giao dịch; xem thử không cấp quyền hay công bố thật.</Note>}{!status&&<Action to="/checkout/status/demo-order" className="mt-5 w-full">Kiểm tra trạng thái đơn minh họa</Action>}{status&&<Action to="/publish" className="mt-5 w-full">Xem tình huống đã xác minh (demo)</Action>}<Action to="/plans" variant="ghost" className="mt-2 w-full">Xem lại gói và điều khoản</Action></div>}
type DemoPartner = {email:string;status:'pending'|'accepted'} | null;
const validPartner=(v:unknown):v is DemoPartner=>v===null||(typeof v==='object'&&v!==null&&typeof (v as {email?:unknown}).email==='string'&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test((v as {email:string}).email)&&['pending','accepted'].includes((v as {status?:string}).status??''));
function SettingsScreen(){
 return <div className="max-w-3xl"><Header name={titles.data} subtitle="KHÁC / TÀI KHOẢN & DỮ LIỆU"/><p className="-mt-3 mb-6 text-muted-foreground">Hai bạn cùng chuẩn bị, hai người có quyền như nhau.</p>
 <h2 className="mb-3 font-display text-xl">Người cùng quản lý</h2><TeamPanel/>
 <p className="mt-4 text-xs leading-5 text-muted-foreground">Sau khi chấp nhận, hai bạn có quyền như nhau ở mọi việc; khi lời mời còn chờ, người được mời chưa xem được dữ liệu nào. Khách mở thiệp không phải người cùng quản lý. Không mời người thứ ba.</p>
 <h2 className="mb-3 mt-8 font-display text-xl">Quyền của hai bạn</h2><div className="overflow-hidden rounded-lg border border-border bg-card"><table className="w-full table-fixed text-left text-[11px] sm:text-sm"><caption className="sr-only">Quyền của hai bạn: cả hai đều có mọi quyền</caption><colgroup><col className="w-[52%]"/><col className="w-[22%]"/><col className="w-[26%]"/></colgroup><thead className="border-b border-border bg-sage"><tr><th scope="col" className="break-words p-2 sm:p-3">Công việc</th><th scope="col" className="break-words p-2 sm:p-3">Người tạo thiệp</th><th scope="col" className="break-words p-2 sm:p-3">Người còn lại</th></tr></thead><tbody>{[['Sửa buổi lễ, việc, ngân sách, khách/CSV, nội dung thiệp','Có','Có'],['Xem phản hồi tham dự','Có','Có'],['Mời, hủy lời mời, rút quyền người còn lại','Có','Có'],['Gói, đơn và công bố thiệp','Có','Có'],['Xuất / yêu cầu xóa dữ liệu','Có','Có']].map(([label,owner,co])=><tr key={label} className="border-b border-border last:border-0"><th scope="row" className="break-words p-2 font-normal sm:p-3">{label}</th><td className="break-words p-2 sm:p-3">{owner}</td><td className="break-words p-2 sm:p-3">{co}</td></tr>)}</tbody></table></div><p className="mt-2 text-xs text-muted-foreground">Người tạo chỉ là nguồn gốc dự án, không có quyền cao hơn. Quyền được kiểm tra trên máy chủ theo tư cách người quản lý đám cưới.</p>
 <h2 className="mb-3 mt-8 font-display text-xl">Dữ liệu của hai bạn</h2><Panel><Row title="Xuất dữ liệu" detail="Chưa hoạt động — sẽ mở ở bước sau; cả hai bạn đều được xuất."/><Row title="Yêu cầu xóa dữ liệu" detail="Chưa hoạt động — sẽ mở ở bước sau; cả hai bạn đều được yêu cầu."/></Panel><Note tone="warm">Xuất/xóa dữ liệu thật chưa hoạt động. Nút dưới đây chỉ đặt lại dữ liệu dùng thử trong phiên xem (việc, ngân sách, khách, thiệp); không đụng tới đám cưới, buổi lễ hay người quản lý đã lưu.</Note><DemoAction variant="outline" className="mt-4" onClick={()=>{resetDemoSession();window.location.reload()}}>Đặt lại dữ liệu demo</DemoAction>
  <div className="mt-8 border-t border-border pt-4"><SmallLabel>TRUY CẬP NHANH</SmallLabel><div className="grid gap-2 sm:grid-cols-2"><Action to="/account" variant="outline">Tài khoản</Action><Action to="/plans" variant="outline">Công bố thiệp</Action><Action to="/rsvp" variant="outline">Phản hồi tham dự</Action></div></div>
 </div>
}
function UtilityScreen({screen}:{screen:ScreenName}){const [partner]=useDemoSession<DemoPartner>('partner',null,validPartner);return <div className="mx-auto max-w-xl"><Header name={titles[screen]} subtitle="TIỆN ÍCH · BẢN DEMO"/>{screen==='login'||screen==='register'?<Panel><div className="space-y-4">{screen==='register'&&<Field label="Tên của bạn" placeholder="Nhập tên"/>}<Field label="Email" type="email" placeholder="ban@example.com"/><Field label="Mật khẩu" type="password" placeholder="Nhập mật khẩu"/></div><Note tone="warm">Mẫu minh họa, chưa có đăng nhập hoặc tạo tài khoản thật.</Note><Action to="/home" className="mt-5 w-full">Xem ứng dụng demo</Action><Action to={screen==='login'?'/register':'/login'} variant="ghost" className="mt-2 w-full">{screen==='login'?'Tạo tài khoản':'Đã có tài khoản?'}</Action></Panel>:screen==='account'?<><Panel><Row title="Hồ sơ" detail="Lan · lan@example.com (thông tin minh họa)"/><Row title="Quyền sử dụng" detail="Chưa có quyền Wedding được xác minh" to="/plans"/><Row title="Người cùng quản lý" detail={partner?`${partner.email} · ${partner.status==='pending'?'chờ chấp nhận':'đã chấp nhận'} (demo)`:"Chưa mời người còn lại · tối đa hai người, quyền như nhau"} to="/settings/data"/></Panel><Action to="/settings/data" className="mt-5">Dữ liệu của hai bạn</Action></>:<><Note tone="warm">Vận hành demo: không có quyền quản trị thật, giao dịch, đối soát hay dữ liệu hỗ trợ.</Note><div className="mt-4 space-y-3"><Panel><Row title="Giao dịch và đối soát" detail="SePay chưa kết nối · không thể xác minh khoản chuyển"/><Row title="Hỗ trợ" detail="Yêu cầu hoàn tiền và lỗi thanh toán sẽ được xử lý ở phase sau"/></Panel></div><Action to="/home" className="mt-5">Về tổng quan</Action></>}</div>}
type DemoAnswer={choice:'yes'|'no';count:number};
type DemoReceipt={name:string;answers:Record<string,DemoAnswer>};
const demoReceiptKey=(token:string)=>`rsvp-demo:${token}`;
/** Lượt vừa nhập của token (key mới nhiều lượt; đọc được cả key cũ một lượt/token). */
export function readDemoReceipt(token:string):DemoReceipt|null {try{const last=sessionStorage.getItem(lastReceiptKey(token));const k=last?receiptKey(token,last):demoReceiptKey(token);const r=parseReceipt(k,sessionStorage.getItem(k));return r?{name:r.name,answers:r.answers}:null}catch{return null}}
function GuestScreen({screen,token}:{screen:ScreenName;token:string}){
 const [events]=useDemoSession<DemoEvent[]>('events',initialEvents,validEvents);
 const [links]=useLinks();
 const view=viewForToken(token,links,events);
 const sideKey:EventSide=view.kind==='unknown'?'chung':view.side;
 const side=({chung:'Link chung','nha-gai':'Nhà gái','nha-trai':'Nhà trai'} as const)[sideKey];
 const shown=view.kind==='ok'?view.events:[];
 const firstAddr=shown.find(e=>e.address.trim());
 const [answers,setAnswers]=useState<Record<string,DemoAnswer>>({});
 const [name,setName]=useState('');const [answerError,setAnswerError]=useState('');const [receipt,setReceipt]=useState<DemoReceipt|null>(null);const [checked,setChecked]=useState(false);
 useEffect(()=>{if(screen==='receipt'){setReceipt(readDemoReceipt(token));setChecked(true)}},[screen,token]);
 if(screen==='expired')return <div className="mx-auto max-w-lg pt-16 text-center"><h1 className="text-4xl">Thiệp đã hết thời hạn</h1><p className="mt-4 text-muted-foreground">Lời mời này không còn hiển thị. Nếu cần biết thêm thông tin, xin liên hệ trực tiếp với gia đình.</p></div>;
 if(view.kind!=='ok')return <GuestClosed kind={view.kind}/>;
 if(screen==='guest')return <div className="pt-8"><InviteCard side={sideKey} shown={shown}/><div className="mt-4 grid grid-cols-2 gap-2"><Button asChild size="lg" className="min-h-11 whitespace-normal text-center"><Link to="/i/$token/rsvp" params={{token}}>Xác nhận tham dự</Link></Button>{firstAddr?<a href={mapUrl(firstAddr.address)} target="_blank" rel="noreferrer" className="inline-flex min-h-11 items-center justify-center gap-2 rounded-md border border-border bg-card px-3 text-center text-sm font-medium">Bản đồ · {firstAddr.name} <ExternalLink className="size-4"/></a>:<span className="inline-flex min-h-11 items-center justify-center rounded-md border border-border px-3 text-center text-xs text-muted-foreground">Chưa có địa chỉ để mở bản đồ</span>}</div><p className="mt-5 text-center text-xs text-muted-foreground">Thiệp và RSVP chỉ là tình huống minh họa.</p></div>;
 if(screen==='receipt')return <div className="pt-16"><SmallLabel>ĐƯỜNG HẸN / {side.toUpperCase()}</SmallLabel><h1 className="text-4xl">Biên nhận minh họa</h1>{checked&&(receipt?<><p className="mt-3 text-sm">Cảm ơn {receipt.name} đã xem lại lựa chọn.</p><Note>Đây là lựa chọn vừa nhập trong phiên demo. Không có phản hồi nào được gửi hoặc lưu trên hệ thống.</Note><div className="mt-5"><SmallLabel>CÂU TRẢ LỜI VỪA NHẬP</SmallLabel><Panel>{shown.filter(e=>receipt.answers[e.id]).map(e=><Row key={e.id} title={e.name} detail={receipt.answers[e.id]?.choice==='yes'?`Có đến · ${receipt.answers[e.id]?.count} người`:'Không đến'}/>)}</Panel></div>{side==='Link chung'&&<Note tone="warm">Phản hồi link chung cần chủ kiểm tra với sổ khách; không tự ghép theo tên.</Note>}</>:<Note tone="warm">Chưa có câu trả lời demo trong phiên này. Trang này không xác nhận đã gửi RSVP.</Note>)}<Button asChild variant="outline" size="lg" className="mt-5 min-h-11 w-full"><Link to="/i/$token" params={{token}}>Quay lại thiệp</Link></Button>{checked&&!receipt&&<Button asChild variant="ghost" size="lg" className="mt-2 min-h-11 w-full"><Link to="/i/$token/rsvp" params={{token}}>Thử trả lời</Link></Button>}</div>;
 return <div className="pt-8"><SmallLabel>ĐƯỜNG HẸN / {side.toUpperCase()}</SmallLabel><h1 className="text-[35px] leading-tight">Bạn sẽ đến cùng mình?</h1><p className="mt-2 text-sm text-muted-foreground">Hãy trả lời riêng cho từng buổi lễ trong thiệp.</p><label className="mt-7 block text-xs font-semibold">Tên người trả lời *<input value={name} onChange={e=>setName(e.target.value)} maxLength={100} className={inputCls}/></label><div className="mt-5 space-y-3">{shown.map(e=>{const a=answers[e.id];return <Panel key={e.id}><h2 className="text-xl">{e.name}</h2><p className="mb-4 text-xs text-muted-foreground">{e.time||'Chưa chốt giờ'} · {e.date?fmtDate(e.date):'Chưa chốt ngày'} · {e.side}</p><div className="grid grid-cols-2 gap-2"><DemoAction variant={a?.choice==='yes'?'default':'outline'} className="rounded-full px-2 text-xs" onClick={()=>setAnswers(v=>({...v,[e.id]:{choice:'yes',count:a?.count??1}}))}>Có, tôi sẽ đến</DemoAction><DemoAction variant={a?.choice==='no'?'default':'outline'} className="rounded-full px-2 text-xs" onClick={()=>setAnswers(v=>({...v,[e.id]:{choice:'no',count:1}}))}>Không đến</DemoAction></div>{a?.choice==='yes'&&<label className="mt-4 flex items-center justify-between gap-2 text-xs">Số người đến (gồm bạn)<input aria-label={`Số người dự ${e.name}`} type="number" min="1" max="20" value={a?.count??1} onChange={v=>setAnswers(prev=>({...prev,[e.id]:{choice:'yes',count:Math.min(20,Math.max(1,Number(v.target.value)||1))}}))} className="h-11 w-20 rounded-md border border-border bg-background px-2 text-center"/></label>}</Panel>})}</div><Button asChild size="lg" className="mt-5 min-h-11 w-full"><Link to="/i/$token/rsvp/receipt" params={{token}} onClick={e=>{if(!name.trim()||shown.length===0||shown.some(ev=>!answers[ev.id])){e.preventDefault();setAnswerError(!name.trim()?'Vui lòng nhập tên.':shown.length===0?'Chưa có buổi lễ để trả lời.':'Hãy chọn Có hoặc Không cho từng buổi lễ.');return}setAnswerError('');try{const rid=`${Date.now().toString(36)}${Math.random().toString(36).slice(2,6)}`;sessionStorage.setItem(receiptKey(token,rid),JSON.stringify({name:name.trim(),answers:Object.fromEntries(shown.map(ev=>[ev.id,answers[ev.id]])),at:new Date().toISOString()}));sessionStorage.setItem(lastReceiptKey(token),rid)}catch{}}}>Xem biên nhận minh họa</Link></Button>{answerError&&<p role="alert" className="mt-2 text-xs text-destructive">{answerError}</p>}<p className="mt-3 text-center text-xs text-muted-foreground">Chưa gửi hoặc lưu phản hồi thật.</p></div>
}
function ChangesWrap(){const [invite]=useDemoSession<InviteDraft>('invite',initialInvite,validInvite);return <ChangesReviewScreen invite={invite}/>}
export function PhaseOne({screen,token='demo',focusId}:{screen:ScreenName;token?:string;focusId?:string}){if(guestScreens.includes(screen))return <GuestShell><GuestScreen screen={screen} token={token}/></GuestShell>;if(screen==='start')return <PublicShell><Onboarding screen="start"/><div className="mt-4 grid gap-2 sm:grid-cols-2"><Action to="/login" variant="outline">Đăng nhập</Action><Action to="/register" variant="ghost">Tạo tài khoản</Action></div></PublicShell>;let content:React.ReactNode;switch(screen){case 'new':case 'events':content=<Onboarding screen={screen}/>;break;case 'home':content=<HomeScreen/>;break;case 'tasks':content=<TasksScreen/>;break;case 'budget':content=<BudgetScreen/>;break;case 'guests':content=<GuestsScreen/>;break;case 'import':content=<CsvImportScreen/>;break;case 'batch':content=<CsvBatchScreen/>;break;case 'content':content=<ContentScreen/>;break;case 'variants':content=<LinksScreen/>;break;case 'preview':content=<PreviewScreen/>;break;case 'plans':content=<PlansScreen/>;break;case 'checkout':content=<CheckoutScreen/>;break;case 'status':content=<CheckoutScreen status/>;break;case 'publish':content=<PublishReviewScreen/>;break;case 'rsvpOwner':content=<OwnerRsvpReconcile/>;break;case 'changes':content=<ChangesWrap/>;break;case 'admin':content=<AdminScreen/>;break;case 'account':content=<AccountScreen/>;break;case 'export':content=<GuestsExportScreen/>;break;case 'history':content=<HistoryScreen/>;break;case 'check':content=<CheckScreen/>;break;case 'team':case 'data':content=<SettingsScreen/>;break;default:content=<UtilityScreen screen={screen}/>;}return <OwnerShell active={screen}><FocusCtx.Provider value={focusId}>{content}</FocusCtx.Provider></OwnerShell>}
